/// <summary>
///    The <c>METItemPackChangeCompletedBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide customer status change business event.
/// </summary>
[BusinessEvents(classStr(METSupplierChangeCompletedBusinessEventContract),
    "@MET:SupplierChangeCompletedBusinessEventName",
    "@MET:SupplierChangeCompletedBusinessEventDescHelpText",
    ModuleAxapta::Vendor)]
internal final class METSupplierChangeCompletedBusinessEvent extends BusinessEventsBase
{
    private ItemId itemId;
    private VendAccount vendAccount;
    private List coverageWareHouseIdList;

}

Method.Source:
/// <summary>
/// Constructs a new METSupplierChangeCompletedBusinessEvent business event.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_vendAccount">Vendor account</param>
/// <param name = "_coverageWareHouseIdList">List of coverage warehouse list</param>
/// <returns>A new <c>METSupplierChangeCompletedBusinessEvent</c> business event.</returns>
public static METSupplierChangeCompletedBusinessEvent newFromSupplierChangeCompleted(ItemId _itemId,VendAccount _vendAccount, list _coverageWareHouseIdList)
{
    METSupplierChangeCompletedBusinessEvent event = new METSupplierChangeCompletedBusinessEvent();

    event.parmItemId(_itemId);
    event.parmVendAccount(_vendAccount);
    event.parmcoverageWareHouseIdList(_coverageWareHouseIdList);

    return event;
}

/// <summary>
/// Get or set vendor account
/// </summary>
/// <param name = "_vendAccount">Vendor account</param>
/// <returns>Vendor account</returns>
public VendAccount parmVendAccount(VendAccount _vendAccount = vendAccount)
{
    vendAccount = _vendAccount;

    return vendAccount;
}

/// <summary>
/// Get or set Item id
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>ItemId</returns>
private ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// List of coverage warehouse list
/// </summary>
/// <param name = "_coverageWareHouseIdList">coverageWareHouseId list</param>
/// <returns>CoverageWareHouseId list</returns>
private List parmCoverageWareHouseIdList(List _coverageWareHouseIdList = coverageWareHouseIdList)
{
    coverageWareHouseIdList = _coverageWareHouseIdList;

    return coverageWareHouseIdList;
}

/// <summary>
/// Overrides to provide Supplier change completed data.
/// </summary>
/// <returns>The <c>METSupplierChangeCompletedBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METSupplierChangeCompletedBusinessEventContract::newFromSupplierChangeCompleted(itemId, vendAccount, coverageWareHouseIdList);
}

/// <summary>
/// creates new object
/// </summary>
private void new()
{
}
